const routes=[['city','map','City overview','81'],['designs','design','Design library','96'],['blocks','blocks','Earlier palette','13'],['installed','blocks','Textures & schematics','215'],['guides','guide','Earlier build guides','96'],['infrastructure','road','Infrastructure','84'],['operations','tools','Build planning','81'],['shapes','image','Reference architecture','102'],['style','image','Earlier cube finish','98'],['references','image','Visual references','3'],['tools','tools','Planning tools','']];
let atlas,designMap,paletteMap,currentRoute='city',search='',librarySector='all',libraryKind='all',libraryFamily='all',selectedPlot='01-01',currentImage='isometric',epoch=0,mainViewer,mediaViewer,activeViewer,layerContext;
const plans=new Map();const content=$('#content');let selectedMaterial=null;
$('#navigation').innerHTML=routes.map(([route,icon,label,count])=>`<a class="nav-link" data-route="${route}" href="#${route}">${ico(icon)}<span>${label}</span>${count?`<span class="nav-count">${count}</span>`:''}</a>`).join('');
$('#navigation').insertAdjacentHTML('beforeend','<a class="nav-link" id="sample2-nav" href="jungle-city/index.html"><span>Sample 2 · Jungle Canyon</span><span class="nav-count">NEW</span></a>');
$('#searchIcon').innerHTML=ico('search');$('#menuToggle').innerHTML=ico('menu');$('#closeMedia').innerHTML=ico('close');
$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('open');$('#closeMedia').onclick=()=>$('#mediaDialog').close();$('#mediaDialog').addEventListener('close',()=>{mediaViewer?.destroy();mediaViewer=null;activeViewer=mainViewer;});
const go=hash=>{location.hash=hash;};
const toast=s=>{const e=$('#toast');e.textContent=s;e.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('visible'),2400);};
const copyText=async value=>{try{await navigator.clipboard.writeText(value);toast('Coordinates copied');}catch{toast(value);}};
function headingCrumb(label){$('#breadcrumbs').innerHTML=`Workspace <span>/</span> ${esc(label)}`;}
async function getPlan(id){if(!plans.has(id)){const d=designMap.get(id);if(!d)throw Error('Design not found');plans.set(id,fetch(d.plan_url).then(r=>{if(!r.ok)throw Error('Could not load the build plan');return r.json();}).catch(e=>{plans.delete(id);throw e;}));}return plans.get(id);}
function selectionMatches(d){if(!search)return true;const q=search.toLowerCase();return `${d.id} ${d.title} ${d.family} ${d.sector||''}`.toLowerCase().includes(q)||atlas.palette.some(p=>`${p.display_name} ${p.registry_name}`.toLowerCase().includes(q)&&d.role_counts?.[p.role])||(atlas.concept_finish?.palette||[]).some(p=>`${p.display_name} ${p.registry_name}`.toLowerCase().includes(q)&&d.finish_role_counts?.[p.role]);}
function stat(icon,n,label){return `<div class="stat"><div class="stat-icon">${ico(icon)}</div><div><b>${n}</b><small>${label}</small></div></div>`;}
function table(headers,rows,cls=''){return `<div class="table-wrap"><table class="${cls}"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function materialName(reg,meta,inventory=false){const p=atlas.palette.find(p=>p.registry_name===reg&&(inventory?p.inventory_metadata:p.placed_metadata)===meta);return p?.display_name||reg;}
function inventoryTable(rows){return table(['Material','Item meta','Items','Stacks + loose','Roles'],rows.map(q=>[`<span class="material-name">${esc(materialName(q.registry_name,q.metadata,true))}</span><span class="material-id">${esc(q.registry_name)}</span>`,q.metadata,`<span class="nowrap">${number(q.items)}</span>`,`${number(q.stacks_64)} + ${q.loose_items}`,`<span class="table-role">${esc(q.roles)}</span>`]),'material-table');}

class Viewport{
 constructor(host,scene,onChange){this.host=host;this.scene=scene;this.onChange=onChange;this.zoom=1;this.panX=0;this.panY=0;this.first=true;this.pointers=new Map();this.cleanup=[];this.canvas=document.createElement('canvas');this.canvas.tabIndex=0;this.canvas.setAttribute('aria-label',scene.label||'Zoomable design. Drag to pan; use plus or minus to zoom, zero to fit.');host.append(this.canvas);this.ctx=this.canvas.getContext('2d');this.ro=new ResizeObserver(()=>this.resize());this.ro.observe(host);this.bind();}
 on(type,fn,opts){this.canvas.addEventListener(type,fn,opts);this.cleanup.push(()=>this.canvas.removeEventListener(type,fn,opts));}
 bind(){this.on('wheel',e=>{e.preventDefault();const p=this.point(e);this.setZoom(this.zoom*Math.exp(-e.deltaY*.0014),p.x,p.y);},{passive:false});this.on('pointerdown',e=>{activeViewer=this;this.canvas.focus({preventScroll:true});const p=this.point(e);this.pointers.set(e.pointerId,p);this.canvas.setPointerCapture(e.pointerId);this.origin=p;this.dragged=false;if(this.pointers.size===2)this.pinch=this.pinchState();this.canvas.classList.add('dragging');});this.on('pointermove',e=>{const p=this.point(e),old=this.pointers.get(e.pointerId);if(old){this.pointers.set(e.pointerId,p);if(this.pointers.size===2){const next=this.pinchState();if(this.pinch?.distance){this.setZoom(this.zoom*next.distance/this.pinch.distance,next.x,next.y);this.panX+=next.x-this.pinch.x;this.panY+=next.y-this.pinch.y;this.draw();}this.pinch=next;this.dragged=true;}else{this.panX+=p.x-old.x;this.panY+=p.y-old.y;if(Math.hypot(p.x-this.origin.x,p.y-this.origin.y)>4)this.dragged=true;this.draw();}}else this.scene.hover?.((p.x-this.panX)/this.zoom,(p.y-this.panY)/this.zoom);});const up=e=>{const p=this.point(e);if(!this.dragged&&this.pointers.size===1)this.scene.click?.((p.x-this.panX)/this.zoom,(p.y-this.panY)/this.zoom,e);this.pointers.delete(e.pointerId);this.pinch=null;if(this.pointers.size===1)this.origin=[...this.pointers.values()][0];if(!this.pointers.size)this.canvas.classList.remove('dragging');};this.on('pointerup',up);this.on('pointercancel',()=>{this.pointers.clear();this.pinch=null;this.canvas.classList.remove('dragging');});this.on('dblclick',e=>{const p=this.point(e);this.scene.double?.((p.x-this.panX)/this.zoom,(p.y-this.panY)/this.zoom,e);});this.on('keydown',e=>{if(['+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0')this.fit();else this.setZoom(this.zoom*(e.key==='-'?1/1.25:1.25));}});this.on('pointerleave',()=>{if(!this.pointers.size)this.scene.leave?.();});}
 point(e){const r=this.canvas.getBoundingClientRect();return{x:e.clientX-r.left,y:e.clientY-r.top};}
 pinchState(){const [a,b]=[...this.pointers.values()];return{x:(a.x+b.x)/2,y:(a.y+b.y)/2,distance:Math.hypot(a.x-b.x,a.y-b.y)};}
 resize(){const r=this.host.getBoundingClientRect();this.w=Math.max(100,r.width);this.h=Math.max(100,r.height);const dpr=Math.min(devicePixelRatio||1,2);this.dpr=dpr;this.canvas.width=Math.round(this.w*dpr);this.canvas.height=Math.round(this.h*dpr);if(this.first){this.first=false;this.fit();}else this.draw();}
 fit(){this.zoom=Math.max(.04,Math.min((this.w-48)/this.scene.width,(this.h-48)/this.scene.height));this.panX=(this.w-this.scene.width*this.zoom)/2;this.panY=(this.h-this.scene.height*this.zoom)/2;this.draw();}
 setZoom(z,ax=this.w/2,ay=this.h/2){const next=Math.min(32,Math.max(.04,z));this.panX=ax-(ax-this.panX)/this.zoom*next;this.panY=ay-(ay-this.panY)/this.zoom*next;this.zoom=next;this.draw();}
 draw(){if(!this.w)return;const c=this.ctx;c.setTransform(this.dpr,0,0,this.dpr,0,0);c.clearRect(0,0,this.w,this.h);c.save();c.translate(this.panX,this.panY);c.scale(this.zoom,this.zoom);this.scene.draw(c,this.zoom);c.restore();this.onChange?.(this);}
 destroy(){this.ro.disconnect();this.cleanup.forEach(f=>f());this.canvas.remove();}
}
function viewerShell(id,hint,extra=''){return `<div class="panel viewer-panel"><div class="viewport" id="${id}"></div><div class="view-toolbar" data-for="${id}"><div class="toolbar-group"><button class="icon-button" data-action="out" aria-label="Zoom out">${ico('minus')}</button><span class="zoom-readout">Fit</span><button class="icon-button" data-action="in" aria-label="Zoom in">${ico('plus')}</button><select class="zoom-select" aria-label="Zoom level"><option value="fit">Fit</option>${[25,50,100,200,400,800,1600,3200].map(n=>`<option value="${n}">${n}%</option>`).join('')}</select><button class="button small quiet" data-action="fit">Fit view</button></div><div class="toolbar-spacer"></div>${extra}<button class="icon-button" data-action="full" aria-label="Open full-screen viewer">${ico('expand')}</button></div><div class="view-hint"><span>${hint}</span><span>Scroll to zoom · drag to pan · 0 to fit</span></div></div>`;}
function mountViewer(id,scene,isMedia=false){const host=document.getElementById(id),toolbar=$(`[data-for="${id}"]`);if(!host)return null;const view=new Viewport(host,scene,v=>{if(!toolbar)return;$('.zoom-readout',toolbar).textContent=Math.round(v.zoom*100)+'%';const sel=$('.zoom-select',toolbar);sel.value=[25,50,100,200,400,800,1600,3200].includes(Math.round(v.zoom*100))?String(Math.round(v.zoom*100)):'fit';});$$('[data-action]',toolbar).forEach(b=>b.onclick=()=>{if(b.dataset.action==='in')view.setZoom(view.zoom*1.3);if(b.dataset.action==='out')view.setZoom(view.zoom/1.3);if(b.dataset.action==='fit')view.fit();if(b.dataset.action==='full')openScene(scene,scene.label||'Design viewer');});$('.zoom-select',toolbar).onchange=e=>{e.target.value==='fit'?view.fit():view.setZoom(Number(e.target.value)/100);};if(isMedia){$('[data-action="full"]',toolbar).remove();mediaViewer=view;}else{mainViewer?.destroy();mainViewer=view;}activeViewer=view;return view;}
function openScene(scene,label,kind='MODEL-DERIVED DESIGN'){mediaViewer?.destroy();$('#mediaTitle').textContent=label;$('#mediaKind').textContent=kind;$('#mediaHost').innerHTML=viewerShell('mediaViewport','Pan and zoom / full source resolution');$('#mediaDialog').showModal();mountViewer('mediaViewport',scene,true);}
async function imageScene(url,label){return new Promise((resolve,reject)=>{const im=new Image();im.onload=()=>resolve({width:im.naturalWidth,height:im.naturalHeight,label,draw:c=>{c.imageSmoothingEnabled=false;c.drawImage(im,0,0);}});im.onerror=()=>reject(Error('This image could not be loaded'));im.src=url;});}
async function showImage(id,url,label){try{const scene=await imageScene(url,label);if(document.getElementById(id))mountViewer(id,scene);}catch(e){const host=document.getElementById(id);if(host)host.innerHTML=`<div class="loading-state"><p>${esc(e.message)}</p><a href="${esc(url)}">Open source image</a></div>`;}}
function bindImages(){ $$('[data-image]').forEach(el=>el.onclick=async()=>{try{openScene(await imageScene(el.dataset.image,el.dataset.title),el.dataset.title,el.dataset.kind||'MODEL-DERIVED DESIGN');}catch(e){toast(e.message);}});}

function cityScene(){const width=916;return{width,height:916,label:'Valier city / local X/Z0..875',draw(c,z){c.fillStyle='#0c1e2c';c.fillRect(20,20,876,876);c.strokeStyle='#345369';c.lineWidth=1/z;for(let n=0;n<=876;n+=96){c.beginPath();c.moveTo(20+n,20);c.lineTo(20+n,896);c.moveTo(20,20+n);c.lineTo(896,20+n);c.stroke();}for(const r of atlas.city.streets){const [x,y,x1,y1]=r.bounds;c.fillStyle='#3a5365';c.fillRect(20+x,20+y,x1-x+1,y1-y+1);}for(const d of atlas.designs.filter(d=>d.kind==='plot')){const [x,y,x1,y1]=d.site_bounds,color=atlas.sectors[d.sector].color,match=selectionMatches(d);c.globalAlpha=match?1:.2;c.fillStyle=d.id===selectedPlot?'#254b57':'#122d3e';c.fillRect(20+x,20+y,x1-x+1,y1-y+1);c.strokeStyle=d.id===selectedPlot?'#b1f1ed':color;c.lineWidth=d.id===selectedPlot?2/z:1/z;c.strokeRect(20+x,20+y,x1-x+1,y1-y+1);c.fillStyle=color;c.font='10px Consolas,monospace';c.fillText(d.id,24+x,34+y);if(z>1.15){c.fillStyle='#c5dbe7';c.font='8px Segoe UI,sans-serif';const words=d.title.split(' ');let line='',yy=48+y;for(const word of words){if((line+' '+word).length>13){c.fillText(line,24+x,yy);line=word;yy+=11;}else line+=(line?' ':'')+word;}if(line)c.fillText(line,24+x,yy);}}c.globalAlpha=1;if(cityScene.grid){c.strokeStyle='#83b5c950';c.lineWidth=.6/z;for(let n=0;n<=876;n+=16){c.beginPath();c.moveTo(20+n,20);c.lineTo(20+n,896);c.moveTo(20,20+n);c.lineTo(896,20+n);c.stroke();}}c.font=`${Math.min(18,12/z)}px Consolas,monospace`;c.fillStyle='#a6c2d4';c.fillText('N / −Z',20,12);c.fillText('+X EAST',814,911);},click(x,y){const d=plotAt(x-20,y-20);if(d){selectedPlot=d.id;renderCityInspector();mainViewer?.draw();mediaViewer?.draw();}},double(x,y){const d=plotAt(x-20,y-20);if(d){if($('#mediaDialog').open)$('#mediaDialog').close();go('design/'+d.id);}},hover(x,y){const d=plotAt(x-20,y-20),canvas=mainViewer?.canvas;if(canvas)canvas.style.cursor=d?'pointer':'grab';}};}
function plotAt(x,z){return atlas.designs.find(d=>d.kind==='plot'&&x>=d.site_bounds[0]&&x<d.site_bounds[2]+1&&z>=d.site_bounds[1]&&z<d.site_bounds[3]+1);}
function renderCity(){headingCrumb('City overview');content.innerHTML=title('YOUR CITY, BLOCK BY BLOCK','A place for everything.','Explore the complete Personal Dimension layout, then zoom into a building, a facade or a single block layer. Design pages open the revised concept finish; the city overview and numbered stages retain the earlier palette.',`<a class="button" href="#designs">${ico('design')}Browse designs</a>`)+`<section class="panel tool-card" id="jungle-sample2"><p class="page-eyebrow">FULL SAMPLE 02 / WHITE CANOPY</p><h2>A complete Jungle Canyon city + modular kit</h2><p>All81 departments,180 graded streets, bridges, tunnels and service galleries. Fifty terrain-adaptable native components with real-block renders, every-level blueprints and WorldEdit schematics, plus seven architectural scenes. Preserved concepts and the first field study remain available.</p><div class="button-row"><a class="button" href="jungle-city/index.html">Explore the full canyon city</a><a class="button quiet" href="jungle-city/index.html#modules">Build from the modular kit</a><a class="button quiet" href="jungle-city/confluence/index.html">Cliff Promenade style &amp; build</a></div><p>Measured preview terrain; actual PDIM survey, support, game import and functional B routing remain open.</p></section><div class="stats-row">${stat('map','81','Assigned city plots')}${stat('blocks','13','Palette roles')}${stat('guide','1,057','Construction stages')}${stat('road','876 × 876','Civil envelope / blocks')}</div><div class="workspace-grid"><section><div class="panel-head panel" style="border-bottom-left-radius:0;border-bottom-right-radius:0"><h2>City masterplan</h2><div class="view-choice">${button('Local 16-block grid','id="gridToggle"','small quiet')}${button('Earlier palette 3D overview',`data-image="${atlas.city.image}" data-title="The whole Valier city"`,'small')}</div></div>${viewerShell('cityViewport','City-local coordinates / north up / all bounds inclusive')}<div class="map-caption">${Object.entries(atlas.sectors).map(([k,v])=>`<span><i class="swatch-dot" style="background:${v.color}"></i>${esc(k)} ${esc(v.name.split(' and ')[0])}</span>`).join('')}</div></section><aside class="panel inspector" id="cityInspector"></aside></div><div class="quick-sections"><a class="quick-card" href="#guides">${ico('guide')}<div>Build with a plan<small>Palettes, stages and exact block layers</small></div></a><a class="quick-card" href="#infrastructure">${ico('road')}<div>Start with infrastructure<small>84 work orders, exact layers and finished roads</small></div></a><a class="quick-card" href="#references">${ico('image')}<div>Explore the visual direction<small>Streets, gardens and facade families</small></div></a></div>`;renderCityInspector();mountViewer('cityViewport',cityScene());$('#gridToggle').onclick=()=>{cityScene.grid=!cityScene.grid;$('#gridToggle').classList.toggle('primary',cityScene.grid);mainViewer.draw();};bindImages();}
function renderCityInspector(){const d=designMap.get(selectedPlot)||designMap.get('01-01');const e=$('#cityInspector');if(!e)return;const [x,z,x1,z1]=d.site_bounds;e.innerHTML=`<div class="panel-head"><h2>Selected plot</h2><span class="badge">${d.sector}</span></div><img class="inspector-image" src="${d.thumbnail}" alt="${esc(d.title)} current finish"><div class="panel-body"><div class="inspector-id">PLOT ${d.id}</div><h2>${esc(d.title)}</h2><p class="resource-note">${pretty(d.family)} / exterior study</p><div class="kv"><span>Footprint</span><b>${x1-x+1} × ${z1-z+1} blocks</b></div><div class="kv"><span>City X</span><b>${x}..${x1}</b></div><div class="kv"><span>City Z</span><b>${z}..${z1}</b></div><div class="kv"><span>Build stages</span><b>${d.stage_count}</b></div><a class="button primary full" href="#design/${d.id}">Open design</a><p class="resource-note">Select a plot to inspect it. Double-click to open its designs and layers.</p></div>`;}
function renderLibrary(guides=false){headingCrumb(guides?'Build guides':'Design library');content.innerHTML=title(guides?'FROM PALETTE TO PLACEMENT':'THE COMPLETE DESIGN COLLECTION',guides?'Earlier palette: numbered build stages.':'One city. A shared design language.',guides?'These 1,057 stages retain the earlier palette. The Reference architecture tab supplies the latest native geometry, matching stock, host layers and guide. Earlier revisions remain available.':'All 81 department plots retain their purposes and reservations. Open the new architecture: layered bays, planted terraces, distinct rooflines and matching construction files.')+`<div class="filter-bar"><div class="filter-chips">${[['all','All sectors'],['NW','Manufacturing'],['NE','Chemistry'],['SW','Biological'],['SE','Power'],['C','Civic']].map(([s,label])=>`<button class="chip ${librarySector===s?'active':''}" data-sector="${s}">${label}</button>`).join('')}</div><div class="toolbar-spacer"></div><select id="kindFilter" aria-label="Design type"><option value="all">All design types</option><option value="plot">City plots</option><option value="module">Components</option></select><select id="familyFilter" aria-label="Building family"><option value="all">All families</option>${[...new Set(atlas.designs.map(d=>d.family))].sort().map(f=>`<option value="${f}">${pretty(f)}</option>`).join('')}</select></div><div class="section-heading"><p id="resultCount"></p><span class="badge neutral">${guides?'MODEL-DERIVED ASSEMBLY':'EXTERIOR STUDIES'}</span></div><div class="design-grid" id="designGrid"></div>`;$('#kindFilter').value=libraryKind;$('#familyFilter').value=libraryFamily;$$('[data-sector]').forEach(b=>b.onclick=()=>{librarySector=b.dataset.sector;renderLibrary(guides);});$('#kindFilter').onchange=e=>{libraryKind=e.target.value;renderCards(guides);};$('#familyFilter').onchange=e=>{libraryFamily=e.target.value;renderCards(guides);};renderCards(guides);}
function renderCards(guides){const ds=atlas.designs.filter(d=>selectionMatches(d)&&(librarySector==='all'||d.sector===librarySector)&&(libraryKind==='all'||d.kind===libraryKind)&&(libraryFamily==='all'||d.family===libraryFamily));$('#resultCount').textContent=ds.length+(ds.length===1?' design':' designs')+(search?' matching “'+search+'”':'');$('#designGrid').innerHTML=ds.map(d=>`<a class="design-card" href="#design/${d.id}${guides?'?tab=stages':''}"><div class="card-image"><img loading="lazy" src="${guides?'true-images/models/'+d.id+'/thumbnail.webp':d.thumbnail}" alt="${esc(d.title)} ${guides?'earlier assembly model':'current finish'}"><span class="card-id">${d.id}</span></div><div class="card-content"><h3>${esc(d.title)}</h3><p>${pretty(d.family)}</p><div class="card-meta"><span>${d.kind==='plot'?d.sector+' / '+d.dimensions_x_y_z[0]+' × '+d.dimensions_x_y_z[2]:'Component study'}</span><span>${d.stage_count} stages</span></div></div></a>`).join('')||'<div class="empty-state"><h2>No designs found</h2><p>Try another plot name, sector or material.</p></div>';}

async function renderDesign(id,params){const d=designMap.get(id);if(!d){go('designs');return;}const thisEpoch=epoch;headingCrumb(d.title);currentImage=params.get('image')||currentImage||'isometric';let tab=params.get('tab')||'shaped';if(!['shaped','finish','overview','facades','palette','layers','stages','downloads','materials'].includes(tab))tab='overview';content.innerHTML=`<div class="loading-state"><h2>Opening ${esc(d.title)}</h2><p>Loading exact block coordinates and construction stages.</p></div>`;let p;try{p=await getPlan(id);}catch(e){if(thisEpoch===epoch)content.innerHTML=`<div class="empty-state"><h2>${esc(e.message)}</h2><a class="button" href="#designs">Back to designs</a></div>`;return;}if(thisEpoch!==epoch)return;
 const tabs=[['shaped','Reference architecture'],['finish','Earlier cube finish'],['materials','Earlier palette'],['overview','Earlier structure views'],['facades','Earlier block projections'],['palette','Earlier block palette'],['layers','Earlier block layers'],['stages','Earlier build stages'],['downloads','Earlier downloads']];
 content.innerHTML=`<div class="design-top"><a class="back-link" href="#designs">Design library</a><span class="badge neutral">${d.id}</span><span class="badge">${d.sector||'COMPONENT'}</span><span class="badge gold">${tab==='shaped'?'Measured plan':'Exterior study'}</span></div>`+title(tab==='shaped'?'Reference architecture / '+pretty(d.family).replace(/ V2$/,''):pretty(d.family),esc(d.title),`${(tab==='shaped'?d.current_architecture?.dimensions_x_y_z:d.dimensions_x_y_z)?.[0]} × ${(tab==='shaped'?d.current_architecture?.dimensions_x_y_z:d.dimensions_x_y_z)?.[2]} local footprint · civil Y${signed((tab==='shaped'?d.current_architecture?.bounds:d.bounds)?.[1])}..${signed((tab==='shaped'?d.current_architecture?.bounds:d.bounds)?.[4])} · ${number(tab==='shaped'?d.current_architecture?.occupied_host_positions:d.positions)} ${tab==='shaped'?'current hosts':'earlier source positions'}`,button(`${ico('download')}${tab==='shaped'?'Native assembly guide':tab==='finish'?'Cube finish guide':'Earlier guide'}`, `data-download-guide="${tab==='shaped'?'reference/models/'+id+'/BUILD_GUIDE.md':tab==='finish'?'concept-match/models/'+id+'/BUILD_GUIDE.md':d.guide_url}"`))+`<div class="tabs" role="tablist" aria-label="Design views">${tabs.map(([k,label])=>`<button class="tab ${tab===k?'active':''}" role="tab" aria-selected="${tab===k}" data-tab="${k}">${label}</button>`).join('')}</div><div id="designView"></div>`;
 $$('[data-tab]').forEach(b=>b.onclick=()=>go(`design/${id}?tab=${b.dataset.tab}`));$('[data-download-guide]').onclick=()=>{const a=document.createElement('a');a.href=$('[data-download-guide]').dataset.downloadGuide;a.download='';a.click();};
 if(tab==='shaped')await renderShapedDesign({viewerShell,showImage,downloadLinks,table,number,mountViewer,isCurrent:()=>epoch===thisEpoch},d,params);
 else if(tab==='finish')await renderConceptDesign({viewerShell,showImage,downloadLinks,table,number,mountViewer,isCurrent:()=>epoch===thisEpoch},d,params);
 else if(tab==='materials')await renderInstalledDesign({viewerShell,showImage,downloadLinks,table,number,isCurrent:()=>epoch===thisEpoch},d,params);
 else if(tab==='stages')renderStages(d,p,Math.max(1,Math.min(p.stages.length,integer(params.get('stage'),1)||1)));
 else if(tab==='downloads')$('#designView').innerHTML=`<div class="panel panel-body"><h2>Your construction files</h2><p class="resource-note">Coordinates, quantities and layers derive from the saved exterior model. Temporary access, tools, machines and crafting ingredients are separate.</p>${downloadLinks(d.downloads)}</div><div class="note">The recipe worksheet deliberately leaves ingredients and crafting operations blank. Final NEI recipes and target-game behavior remain unverified.</div>`;
 else if(tab==='layers')renderLayers(d,p,params);
 else if(tab==='palette')renderDesignPalette(d,p);
 else renderDesignImages(d,p,tab);
}
function designInspector(d,p){const site=d.site_bounds;return `<aside class="panel inspector"><div class="panel-head"><h2>Design details</h2></div><div class="panel-body"><div class="inspector-id">${d.id} / ${d.kind==='plot'?'CITY PLOT':'COMPONENT'}</div><h2>${esc(d.title)}</h2><dl class="property-list"><dt>Footprint</dt><dd>${d.dimensions_x_y_z[0]} × ${d.dimensions_x_y_z[2]} blocks</dd><dt>Height / civil block levels</dt><dd>Y${signed(d.bounds[1])}..${signed(d.bounds[4])}</dd>${site?`<dt>City reservation</dt><dd class="mono">X${site[0]}..${site[2]}<br>Z${site[1]}..${site[3]}</dd>`:''}<dt>Construction stages</dt><dd>${p.stages.length} / ${number(p.occupied_positions)} model cells</dd><dt>Coordinates</dt><dd>NW origin · +X east · +Z south<br>Y0 = future walkable surface S</dd></dl><div class="note">${d.id==='01-01'?'Steam Works v2 geometry is reused unchanged. Its original building-local Y becomes civil Y after subtracting 8.':'Saved exterior geometry. Interior routes, machines, utilities and game tests remain open.'}</div>${button('Open block layers',`data-open-layers="${d.id}"`,'primary full')}</div></aside>`;}
function bindOpenLayers(){ $$('[data-open-layers]').forEach(b=>b.onclick=()=>go('design/'+b.dataset.openLayers+'?tab=layers'));}
function renderDesignImages(d,p,tab){let choices=tab==='facades'?[['north','North'],['south','South'],['west','West'],['east','East'],['roof','Roof plan'],['card','Design card']]:[['isometric','3D model'],['card','Design card'],['progress','Construction progress']];if(!choices.some(([k])=>k===currentImage))currentImage=choices[0][0];$('#designView').innerHTML=`<div class="detail-layout"><div><div class="filter-bar view-choice">${choices.map(([k,label])=>`<button class="chip ${currentImage===k?'active':''}" data-view-image="${k}">${label}</button>`).join('')}<div class="toolbar-spacer"></div><a class="button small quiet" href="${d.images[currentImage]}" download>${ico('download')}Image</a></div>${viewerShell('designViewport',tab==='facades'?'Installed-texture projections / construct from full layers':'Saved geometry / installed texture pixels')}<div class="note">${tab==='facades'?'North/south sheet columns increase X east; west/east columns increase Z south. Roof plans have north up. These projections include hidden depth; use block layers for placement.':'The source model includes all counted positions. Some overview images omit the basement or use a declared presentation cutaway.'}</div></div>${designInspector(d,p)}</div>`;$$('[data-view-image]').forEach(b=>b.onclick=()=>{currentImage=b.dataset.viewImage;renderDesignImages(d,p,tab);});bindOpenLayers();showImage('designViewport',d.images[currentImage],d.id+' / '+d.title+' / '+pretty(currentImage));}
function renderDesignPalette(d,p){$('#designView').innerHTML=`<div class="detail-layout"><div>${viewerShell('paletteViewport','Installed base textures / source identities and metadata')}<div class="section-heading"><h2>Gathering stock</h2><span class="badge neutral">INVENTORY ITEMS</span></div><div class="panel">${inventoryTable(p.inventory_stock)}</div><div class="note">Placed states and inventory are counted separately. Top slabs consume ordinary slab item0. Player-placed oak leaves use item0 with placed persistence4. G/Q glass is combined in the inventory table; Q is dry glass fill.</div></div>${designInspector(d,p)}</div>`;bindOpenLayers();showImage('paletteViewport',d.images.palette,d.title+' / block palette');}

function layerGrid(p,y){const w=p.dimensions_x_y_z[0],d=p.dimensions_x_y_z[2],roles=new Array(w*d).fill(null),owners=new Uint8Array(w*d);let count=0;for(const s of p.stages)for(const [cy,z,a,b,r] of s.rle)if(cy===y)for(let x=a;x<=b;x++){roles[z*w+x]=r;owners[z*w+x]=s.sequence;count++;}return{w,d,roles,owners,count};}
function layerScene(d,p,state){let selected=null;const scene={isLayer:true,width:p.dimensions_x_y_z[0]*16+112,height:p.dimensions_x_y_z[2]*16+122,label:d.id+' / exact block layer',draw(c,z){const g=state.grid,ox=56,oy=57;c.fillStyle='#0b1c28';c.fillRect(ox,oy,g.w*16,g.d*16);for(let zz=0;zz<g.d;zz++)for(let x=0;x<g.w;x++){const i=zz*g.w+x,role=g.roles[i];if(role){const active=!state.stage||g.owners[i]===state.stage;c.globalAlpha=active?1:.18;c.fillStyle=!state.stage?paletteMap.get(role).color:active?'#e1ba75':paletteMap.get(role).color;c.fillRect(ox+x*16,oy+zz*16,16,16);if(z*16>=14){c.fillStyle=active?'#071824':'#a7c0d2';c.font='11px Consolas,monospace';c.textAlign='center';c.fillText(role,ox+x*16+8,oy+zz*16+12);}}}c.globalAlpha=1;c.textAlign='left';if(z>.18){c.strokeStyle='#345165';c.lineWidth=.6/z;for(let x=0;x<=g.w;x++){c.beginPath();c.moveTo(ox+x*16,oy);c.lineTo(ox+x*16,oy+g.d*16);c.stroke();}for(let zz=0;zz<=g.d;zz++){c.beginPath();c.moveTo(ox,oy+zz*16);c.lineTo(ox+g.w*16,oy+zz*16);c.stroke();}}c.font='12px Consolas,monospace';c.fillStyle='#a3bfd0';for(let x=0;x<g.w;x++)if(x%8===0||x===g.w-1)c.fillText(String(x),ox+x*16,oy-13);for(let zz=0;zz<g.d;zz++)if(zz%8===0||zz===g.d-1)c.fillText(String(zz),ox-33,oy+zz*16+12);c.fillStyle='#80d8df';c.fillText('+X EAST',ox+g.w*16-73,25);c.fillText('N / −Z',ox,25);c.fillStyle='#a3bfd0';c.fillText('+Z SOUTH / CIVIL Y'+signed(state.y),ox,oy+g.d*16+28);if(selected){c.strokeStyle='#aaf0ef';c.lineWidth=2/z;c.strokeRect(ox+selected.x*16,oy+selected.z*16,16,16);}},hover(x,z){const cell=hit(x,z);if(cell&&!state.pinned)inspectBlock(d,p,state,cell.x,cell.z);},click(x,z){const cell=hit(x,z);if(cell){selected=cell;state.pinned=cell;inspectBlock(d,p,state,cell.x,cell.z,true);mainViewer?.draw();mediaViewer?.draw();}}};function hit(x,z){const xx=Math.floor((x-56)/16),zz=Math.floor((z-57)/16);return xx>=0&&zz>=0&&xx<state.grid.w&&zz<state.grid.d?{x:xx,z:zz}:null;}return scene;}
function inspectBlock(d,p,state,x,z,pin=false){const el=$('#blockInspect');if(!el)return;const i=z*state.grid.w+x,role=state.grid.roles[i],material=paletteMap.get(role),owner=state.grid.owners[i],city=d.site_bounds?`City X${x+d.site_bounds[0]} / Z${z+d.site_bounds[1]}`:'Detached component coordinates';el.innerHTML=`<div class="tiny-heading">${pin?'SELECTED BLOCK':'BLOCK INSPECTOR'}</div><h3>X${x} · Y${signed(state.y)} · Z${z}</h3><p>${city}</p>${material?`<p><strong>${esc(material.display_name)}</strong></p><p><code>${esc(material.registry_name)}</code></p><p>Placed meta ${material.placed_metadata} · item meta ${material.inventory_metadata}</p><p>Construction ${p.stages[owner-1]?.id||''}</p>`:'<p>Empty source-model cell.<br>This does not instruct excavation.</p>'}${button(ico('copy')+'Copy coordinates','id="copyCell"','small quiet')}`;if($('#mediaDialog').open&&mediaViewer?.scene.isLayer)$('#mediaKind').textContent='X'+x+' / Y'+signed(state.y)+' / Z'+z+' · '+(material?material.display_name+' · meta'+material.placed_metadata:'Empty source cell');$('#copyCell').onclick=()=>copyText(`${d.id} local X${x} Y${state.y} Z${z}; ${city}; ${material?material.registry_name+':'+material.placed_metadata:'empty'}; world unassigned`);}
function renderLayers(d,p,params){const stage=Math.max(0,Math.min(p.stages.length,integer(params.get('stage'),0))),y=Math.max(d.bounds[1],Math.min(d.bounds[4],params.has('y')?integer(params.get('y'),d.bounds[1]):stage?p.stages[stage-1].civil_y[0]:Math.min(Math.max(5,d.bounds[1]),d.bounds[4]))),state={stage,y,grid:layerGrid(p,y)};layerContext=state;$('#designView').innerHTML=`<div class="detail-layout"><section><div class="panel" style="border-radius:12px 12px 0 0"><div class="layer-controls"><label>Construction stage<select id="layerStage" class="stage-select"><option value="0">Complete model</option>${p.stages.map(s=>`<option value="${s.sequence}">${s.id} / ${esc(s.title)}</option>`).join('')}</select></label><label>Civil Y<select id="layerLevel">${Array.from({length:p.dimensions_x_y_z[1]},(_,i)=>i+d.bounds[1]).map(y=>`<option value="${y}">${signed(y)}</option>`).join('')}</select></label><label>Layer level<input type="range" id="layerSlider" min="${d.bounds[1]}" max="${d.bounds[4]}" value="${y}" aria-label="Layer level"></label><div class="toolbar-spacer"></div><button class="icon-button" id="lowerLayer" aria-label="Lower layer">${ico('minus')}</button><button class="icon-button" id="higherLayer" aria-label="Higher layer">${ico('plus')}</button></div></div>${viewerShell('layerViewport','One square = one model position / empty cells are not excavation')}<div class="note"><strong id="layerCount"></strong> Hover or tap a block to inspect its identity, metadata and construction stage. A selected stage is gold; other model cells are muted.</div></section><aside class="panel inspector"><div class="panel-head"><h2>Layer details</h2></div><div class="panel-body"><span class="badge">LOCAL BLOCK GRID</span><dl class="property-list"><dt>Current civil level</dt><dd id="levelText"></dd><dt>Model plan</dt><dd>${p.dimensions_x_y_z[0]} × ${p.dimensions_x_y_z[2]} cells</dd><dt>World position</dt><dd>S and world anchor unassigned</dd></dl><div class="block-inspection" id="blockInspect"><div class="tiny-heading">BLOCK INSPECTOR</div><p class="resource-note">Move over a grid cell to see the role, block identity and exact coordinates.</p></div>${button('Open selected stage','id="openSelectedStage"','full')}<p class="resource-note">Both half-slab states use one inventory slab item. The grid reports block positions, not crafting ingredients.</p></div></aside></div>`;
 const scene=layerScene(d,p,state);mountViewer('layerViewport',scene);$('#layerStage').value=String(stage);$('#layerLevel').value=String(y);function update(level,which=state.stage){state.y=Math.max(d.bounds[1],Math.min(d.bounds[4],Number(level)));state.stage=Number(which);state.grid=layerGrid(p,state.y);$('#layerLevel').value=String(state.y);$('#layerSlider').value=String(state.y);$('#layerStage').value=String(state.stage);const count=state.stage?state.grid.owners.reduce((n,s)=>n+(s===state.stage),0):state.grid.count;$('#layerCount').textContent=number(count)+' selected positions on this layer. ';$('#levelText').textContent='Y'+signed(state.y)+' / world block Y = S'+signed(state.y);if(state.pinned)inspectBlock(d,p,state,state.pinned.x,state.pinned.z,true);mainViewer.draw();mediaViewer?.draw();history.replaceState(null,'','#design/'+d.id+'?tab=layers&y='+state.y+'&stage='+state.stage);}
 $('#layerLevel').onchange=e=>update(e.target.value);$('#layerSlider').oninput=e=>update(e.target.value);$('#layerStage').onchange=e=>{const s=Number(e.target.value);update(s?p.stages[s-1].civil_y[0]:state.y,s);};$('#lowerLayer').onclick=()=>update(state.y-1);$('#higherLayer').onclick=()=>update(state.y+1);$('#openSelectedStage').onclick=()=>go('design/'+d.id+'?tab=stages&stage='+(state.stage||1));update(y,stage);
}
function renderStages(d,p,n){const stage=p.stages[n-1];$('#designView').innerHTML=`<div class="stage-layout"><aside class="stage-list" aria-label="Construction stages">${p.stages.map(s=>`<button class="stage-item ${s.sequence===n?'active':''}" data-stage="${s.sequence}"><strong>${s.id}</strong><span>${esc(s.title.split(' / ')[0])}</span><small>${number(s.new_positions)} new positions</small></button>`).join('')}</aside><div class="section-stack"><article class="panel stage-content"><div class="design-top"><span class="badge">${stage.id} / ${p.stages.length} STAGES</span><span class="badge neutral">CIVIL Y${signed(stage.civil_y[0])}..${signed(stage.civil_y[1])}</span></div><h2>${esc(stage.title.split(' / ')[0])}</h2><p class="resource-note">Local X${stage.bounds_xyz_inclusive[0]}..${stage.bounds_xyz_inclusive[3]} / Z${stage.bounds_xyz_inclusive[2]}..${stage.bounds_xyz_inclusive[5]}. These bounds locate the work; they do not instruct a solid fill.</p><div class="stage-quantity"><div><b>${number(stage.new_positions)}</b><small>New positions</small></div><div><b>${number(stage.cumulative_positions)}</b><small>Cumulative model positions</small></div></div><ol class="stage-actions">${stage.actions.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><div class="actions">${button(ico('grid')+'View this stage in layers','id="showStageGrid"','primary')}${button(ico('image')+'Construction progress',`data-image="${d.images.progress}" data-title="${esc(d.title)} / construction progress"`)}</div><div class="section-heading"><h3>Gather for this stage</h3><span class="badge neutral">INVENTORY ITEMS</span></div>${inventoryTable(stage.inventory)}<div class="stage-bottom">${button('Previous step',`id="previousStage" ${n===1?'disabled':''}`,'quiet')}${button('Next step',`id="nextStage" ${n===p.stages.length?'disabled':''}`)}</div></article><div class="source-box">Every final-model cell belongs to one numbered stage. Material recipes, machine fit, accessible interiors and target-game testing remain open. Construction is not marked complete by viewing a stage.</div></div></div>`;$$('[data-stage]').forEach(b=>b.onclick=()=>go(`design/${d.id}?tab=stages&stage=${b.dataset.stage}`));$('#previousStage').onclick=()=>go(`design/${d.id}?tab=stages&stage=${Math.max(1,n-1)}`);$('#nextStage').onclick=()=>go(`design/${d.id}?tab=stages&stage=${Math.min(p.stages.length,n+1)}`);$('#showStageGrid').onclick=()=>go(`design/${d.id}?tab=layers&stage=${n}&y=${stage.civil_y[0]}`);bindImages();}

function renderBlocks(){headingCrumb('Earlier block palette');content.innerHTML=title('MATERIALS WITH A PURPOSE','The Valier block palette.','See the actual base textures, block identities and placement states behind every design.',button(ico('image')+'Common palette',`data-image="${atlas.common_palette_image}" data-title="Common city block palette"`))+`<div class="note">Registry identities and metadata have installed-file evidence. Installed block-color multipliers are used; foliage uses its default item tint. Recipes, biome/shader appearance and game behavior remain open.</div><div class="palette-grid" id="paletteGrid"></div>`;renderBlockCards();bindImages();}
function renderBlockCards(){const ps=atlas.palette.filter(p=>!search||`${p.role} ${p.display_name} ${p.registry_name} ${p.usage}`.toLowerCase().includes(search.toLowerCase()));$('#paletteGrid').innerHTML=ps.map(p=>`<button class="block-card ${selectedMaterial===p.role?'selected':''}" data-material="${p.role}"><div class="block-card-head"><div class="block-swatch" style="background-image:url('${p.texture_url}')"></div><div><div class="block-role">ROLE ${p.role}</div><h3>${esc(p.display_name)}</h3></div></div><code>${esc(p.registry_name)}</code><p>Placed meta <strong>${p.placed_metadata}</strong> / item meta <strong>${p.inventory_metadata}</strong></p><p>${esc(p.usage)}</p></button>`).join('')+(selectedMaterial&&ps.some(p=>p.role===selectedMaterial)?materialUsage(selectedMaterial):'')+(ps.length?'':'<div class="empty-state"><h2>No matching blocks</h2><p>Try a block name or registry identity.</p></div>');$$('[data-material]').forEach(b=>b.onclick=()=>{selectedMaterial=selectedMaterial===b.dataset.material?null:b.dataset.material;renderBlockCards();});}
function materialUsage(role){const p=paletteMap.get(role),uses=atlas.designs.filter(d=>d.role_counts?.[role]);return `<div class="material-expanded"><div class="section-heading" style="margin-top:0"><h2>${esc(p.display_name)} / where it is used</h2><span class="badge">${uses.length} DESIGNS</span></div><p class="resource-note">Counts below are positions for this role in each separate model. They are not a combined city purchase bill; components may be alternatives or existing civil crops.</p><div class="usage-list">${uses.map(d=>`<a href="#design/${d.id}?tab=palette"><span>${d.id} / ${esc(d.title)}</span><b>${number(d.role_counts[role])}</b></a>`).join('')||'<p>Usage details are in each model palette.</p>'}</div></div>`;}

function renderInfrastructure(params){headingCrumb('Infrastructure');const order=atlas.infrastructure.orders.find(o=>o.id===(params.get('order')||'WO01'))||atlas.infrastructure.orders[0];content.innerHTML=title('INFRASTRUCTURE FIRST','Build the roads, block by block.','The complete civil field guide covers all84 work orders with finished road materials, exact layers, clearance, cap handovers and sited smooth lamps.')+`<section class="panel tool-card" id="through-ev-guide"><h2>Steam through EV: manual construction guide</h2><p>25 department layouts, exact LV/MV/HV/EV stage grids, light-fuel/diesel primary supply and limited steam backup. Zoom and pan the plans, inspect block coordinates and configurations, and check the operating budget.</p><div class="button-row"><a class="button" href="ev/index.html">Open the guide through EV</a><a class="button quiet" href="ev/Valier_Through_EV_Architecture_ONLY.zip">27 architecture-only ghost schematics</a><a class="button quiet" href="ev/Valier_Through_EV_Fieldbook.pdf">28-page fieldbook</a></div><p><b>Survival/manual building:</b> schematic files contain building fabric only. Machines, tanks, coils, pipes, cables and conduits are excluded; use Schematica with Printer OFF. Equipment remains in separate placement/connection guides. Static checks passed; recipes, formation, flow and game commissioning remain open.</p></section><section class="panel tool-card" id="steam-utility-guide"><h2>Steam Works: connected utility plan</h2><p>Two confirmed36-HP Railcraft solid-fuel boilers, six steel steam processors, a576,000L water buffer and optional HV backup. Exact pipe/cable routes, connection faces, service-gallery transition and49 marked removals fit the current refined01-01 shell.</p><div class="button-row"><a class="button" href="steam/index.html">Open Steam Works layers &amp; utility guide</a><a class="button quiet" href="steam/Steam_Works_Utilities_Fieldbook.pdf">15-page fieldbook</a><a class="button quiet" href="steam/Steam_Works_Utilities_Pack.zip">Complete offline plan</a></div><p>Source-checked against installed GTNH2.9.2. Static coordinates, network capacity and access checks pass; game formation, actual flow, recipes and external water/fuel supplies remain to commission. Steam distribution and HV backup have separate operating allocations.</p></section><section class="panel tool-card"><h2>Complete roads &amp; infrastructure field guide</h2><p>84 work orders · 1,512 exact layer grids · 351 sited smooth lamps · 1,440 thin cyan curb inserts. Uses Agon13 road panels and Agon15 paving, with separate full-block/cut-piece stock. Blocks and supporting shape sources checked against the installed2.9.2 client; game sample and actual lighting checks remain open.</p><div class="button-row"><a class="button" href="civil/index.html">Open the block-by-block field guide</a><a class="button quiet" href="civil/Valier_Civil_Fieldbook_V2.pdf">104-page printable fieldbook</a><a class="button quiet" href="civil/Valier_Civil_Fieldguide_V2.zip">Complete offline pack</a></div><p>Begin with WO01/M11 after the PDIM survey. The first stair pages show required-clear and temporary-cap cells as well as permanent blocks. Steam Works now has a separate connected utility guide above; other departments still need their networks designed.</p></section><div class="section-heading"><h2>Earlier northwest civil core pack</h2><p>Preserved19-order reference below. Its original all-stone material bill and schematic files are separate from the finished field guide above.</p></div>`+`<div class="stats-row">${stat('road','19','Northwest work orders')}${stat('blocks','198,608','Permanent P1 positions')}${stat('guide','440','Peak end-state cap bricks')}${stat('map','Not created','PDIM survey status')}</div><div class="filter-bar"><label class="field">Work order<select id="workOrder">${atlas.infrastructure.orders.map(o=>`<option value="${o.id}">${o.id} / ${esc(o.name)}</option>`).join('')}</select></label><div class="toolbar-spacer"></div>${button('Blueprint sheet',`data-image="${order.blueprint_image_url}" data-title="${order.id} / coordinate blueprint" data-kind="TECHNICAL BLUEPRINT / SYMBOLIC MATERIAL KEY"`)}${button('Survey sheet',`data-image="${atlas.infrastructure.sheets.find(s=>s.id==='P0-01').url}" data-title="P0 / blank survey sheet"`)}${button('Stakeout sheet',`data-image="${atlas.infrastructure.sheets.find(s=>s.id==='P0-02').url}" data-title="P0 / road stakeout"`)}</div><div class="detail-layout"><section>${viewerShell('infraViewport','Installed-block order view / right panel is a labeled display cutaway')}<div class="section-heading"><h2>Order files</h2></div>${downloadLinks(order.downloads)}</section><aside class="panel inspector"><div class="panel-head"><h2>${order.id}</h2><span class="badge gold">PLANNED</span></div><div class="panel-body"><h2>${esc(order.name)}</h2><p class="resource-note">${esc(order.purpose)}</p><div class="kv"><span>New permanent</span><b>${number(order.new_permanent_positions)}</b></div><div class="kv"><span>Caps / add</span><b>${order.temporary_caps_add}</b></div><div class="kv"><span>Caps / remove</span><b>${order.temporary_caps_remove}</b></div><div class="kv"><span>Caps / remaining</span><b>${order.temporary_caps_remaining}</b></div><dl class="property-list"><dt>City bounds</dt><dd>X${order.bounds[0]}..${order.bounds[2]} / Z${order.bounds[1]}..${order.bounds[3]}</dd><dt>Permanent inventory</dt><dd>${order.stock.map(s=>`${number(s.items)} ${esc(s.registry_name)} item${s.inventory_metadata}`).join('<br>')}</dd></dl><div class="note gold">Temporary caps are additional, reusable blocks. End-state caps do not include extra handover overlap, lights, markers or temporary support.</div></div></aside></div><div class="section-heading"><h2>Print and construction packs</h2></div>${downloadLinks([...atlas.infrastructure.downloads,...atlas.city.downloads])}<div class="section-heading"><h2>Master blueprint sheets</h2></div><div class="design-grid">${atlas.city.master_sheets.map(s=>`<button class="design-card" data-image="${s.url}" data-title="${esc(s.title)}"><div class="card-image"><img loading="lazy" src="${s.url}" alt="${esc(s.title)}"></div><div class="card-content"><h3>${esc(s.title)}</h3></div></button>`).join('')}</div>`;$('#workOrder').value=order.id;$('#workOrder').onchange=e=>go('infrastructure?order='+e.target.value);showImage('infraViewport',order.image_url,order.id+' / installed-block permanent addition');bindImages();}
function renderReferences(){headingCrumb('Visual references');content.innerHTML=title('THE ARCHITECTURAL DIRECTION, IN REAL BLOCKS','Streets. Gardens. Distinctive facades.','Browse the White Canopy art and its installed-texture translations, then explore the original Serenity City architectural set.')+`<section class="panel tool-card" id="white-canopy-references"><h2>White Canopy · Jungle Canyon</h2><p>Compare the supplied aerial and promenade with their GTNH 2.9.2 palette edits and exact installed-texture renders.</p><div class="reference-grid">${[['aerial','Canyon overview'],['promenade','Cliff promenade']].map(([angle,name])=>`<article class="reference-card"><a href="jungle-city/confluence/index.html?view=${angle}&amp;mode=palette"><img src="jungle-city/confluence/${angle}-palette-art.webp" alt="${name} · palette-guided concept edit" loading="lazy"></a><div class="panel-body"><h3>${name}</h3><a class="button" href="jungle-city/confluence/index.html?view=${angle}&amp;mode=palette">Compare the three views</a></div></article>`).join('')}</div><a class="button" href="jungle-city/confluence/index.html#build">Build the cliff frontage</a></section><section class="panel tool-card"><h2>Rebuilt around the three Serenity City boards</h2><p>Layered window bays, planted terraces, thin cornices, detailed lamps, native diagonal ribs, real water/V squares and six roof families. The 102 explicit models have matching native exports, coordinates, host layers and measured elevations.</p><a class="button primary" href="#shapes">Open the architectural construction set</a></section><div class="note">Neutral material renders show the actual selected block textures and color multipliers. They are coordinate renderings, not game screenshots. Technical maps and construction grids remain labeled plans.</div><div class="reference-grid">${atlas.actual_references.map(c=>`<article class="reference-card"><img src="${c.url}" alt="${esc(c.title)} / installed-block rendering" loading="lazy"><div class="panel-body"><div><span class="badge">INSTALLED-BLOCK RENDER</span><h2 style="margin-top:10px">${esc(c.title)}</h2><p class="resource-note">${esc(c.note)}</p></div>${button('Zoom actual-block board',`data-image="${c.url}" data-title="${esc(c.title)} / installed blocks" data-kind="SAVED COORDINATES / INSTALLED TEXTURES"`)}</div></article>`).join('')}</div>${atlas.previous_architecture_references?`<details class="panel tool-card"><summary>Previous architectural reconstruction — preserved</summary><div class="reference-grid">${atlas.previous_architecture_references.map(c=>`<article class="reference-card"><img loading="lazy" src="${c.url}" alt="Previous architecture / ${esc(c.title)}"><div class="panel-body"><h3>${esc(c.title)}</h3>${button('Zoom previous architecture',`data-image="${c.url}" data-title="Previous architecture / ${esc(c.title)}" data-kind="PRESERVED PREVIOUS RECONSTRUCTION"`)}</div></article>`).join('')}</div></details>`:''}<div class="section-heading"><h2>Earlier palette sector collections</h2></div><div class="design-grid">${Object.entries(atlas.city.sector_images).map(([k,url])=>`<button class="design-card" data-image="${url}" data-title="${esc(atlas.sectors[k].name)} / installed-block collection" data-kind="INSTALLED-BLOCK RENDERS / COLLECTION, NOT PLACEMENT MAP"><div class="card-image"><img loading="lazy" src="${url}" alt="${esc(k)} sector / installed textures"></div><div class="card-content"><h3>${k} / ${esc(atlas.sectors[k].name)}</h3></div></button>`).join('')}</div>${atlas.previous_finish_references?`<details class="panel tool-card"><summary>Earlier cube-finish boards — preserved</summary><div class="reference-grid">${atlas.previous_finish_references.map(c=>`<article class="reference-card"><img loading="lazy" src="${c.url}" alt="Earlier cube finish / ${esc(c.title)}"><div class="panel-body"><h3>${esc(c.title)}</h3>${button('Zoom earlier finish',`data-image="${c.url}" data-title="Earlier cube finish / ${esc(c.title)}" data-kind="EARLIER CUBE FINISH / INSTALLED BLOCKS"`)}</div></article>`).join('')}</div></details>`:''}${atlas.previous_material_references?`<details class="panel tool-card"><summary>Previous installed-block palette boards — preserved</summary><div class="reference-grid">${atlas.previous_material_references.map(c=>`<article class="reference-card"><img loading="lazy" src="${c.url}" alt="Previous palette / ${esc(c.title)}"><div class="panel-body"><h3>${esc(c.title)}</h3>${button('Zoom previous palette',`data-image="${c.url}" data-title="Previous palette / ${esc(c.title)}" data-kind="PREVIOUS PALETTE / INSTALLED BLOCKS"`)}</div></article>`).join('')}</div></details>`:''}<details class="panel tool-card concept-archive"><summary>Original concept archive — 3 preserved AI boards</summary><p>Historical style references. These are AI concepts, not actual-block views or measured blueprints. Flowers, hanging greenery, signs and bridges are not automatically modeled.</p><div class="reference-grid">${atlas.concepts.map(c=>`<article class="reference-card"><img src="${c.url}" alt="Archived AI concept / ${esc(c.title)}" loading="lazy"><div class="panel-body"><div><span class="badge gold">ARCHIVED AI CONCEPT</span><h2>${esc(c.title)}</h2></div>${button('Open original concept',`data-image="${c.url}" data-title="Original concept / ${esc(c.title)}" data-kind="ARCHIVED AI CONCEPT / NOT A MEASURED BLUEPRINT"`)}</div></article>`).join('')}</div></details>`;bindImages();}

function renderTools(){headingCrumb('Planning tools');content.innerHTML=title('PRACTICAL HELP, WHILE YOU BUILD','A few useful calculations.','Convert quantities into stacks, locate a plot and translate a building’s local coordinates into the city grid. These tools do not place blocks or change a world.')+`<div class="tool-grid"><section class="panel tool-card"><h2>Stack calculator</h2><p>Convert an inventory quantity to stacks and loose items. This calculates item storage, not crafting recipes.</p><div class="form-row"><label class="field">Items<input id="stackItems" type="number" min="0" step="1" value="1964"></label><label class="field">Items per stack<input id="stackSize" type="number" min="1" step="1" value="64"></label></div><output class="tool-output full" id="stackOutput" style="display:block"></output></section><section class="panel tool-card"><h2>96-block tile setout</h2><p>Keep the 12-wide north/west roads and generic hall reservation. The HQ exception stays 65 × 65.</p><div class="form-row"><label class="field">Tile column / east<input id="tileX" type="number" min="0" max="8" value="4"></label><label class="field">Tile row / south<input id="tileZ" type="number" min="0" max="8" value="4"></label></div><output class="tool-output full" id="tileOutput" style="display:block"></output></section><section class="panel tool-card"><h2>Local to city coordinates</h2><p>Building-local X/Z0 is its northwest reservation corner. Civil Y already uses surface S.</p><label class="field">City plot<select id="coordPlot">${atlas.designs.filter(d=>d.kind==='plot').map(d=>`<option value="${d.id}">${d.id} / ${esc(d.title)}</option>`).join('')}</select></label><div class="form-row"><label class="field">Local X<input id="coordX" type="number" value="0"></label><label class="field">Local Z<input id="coordZ" type="number" value="0"></label></div><output class="tool-output full" id="coordOutput" style="display:block"></output></section><section class="panel tool-card"><h2>Viewer shortcuts</h2><p>Focus a map, image or layer canvas to use its zoom controls. Every viewer also supports full screen.</p><div class="keyboard-list"><kbd>+</kbd><span>Zoom in</span><kbd>−</kbd><span>Zoom out</span><kbd>0</kbd><span>Fit the full design</span><kbd>Esc</kbd><span>Close the full-screen viewer</span><kbd>Ctrl K</kbd><span>Search designs or materials</span><kbd>Drag</kbd><span>Pan around the current drawing</span></div><div class="note">Image percentages refer to source pixels. Block-layer squares refer to exact model positions. AI concept pixels do not establish block measurements.</div></section></div>`;
 const updateStacks=()=>{const q=Math.max(0,Math.floor(Number($('#stackItems').value)||0)),size=Math.max(1,Math.floor(Number($('#stackSize').value)||64));$('#stackOutput').textContent=number(Math.floor(q/size))+' full stacks + '+q%size+' loose items\n'+number(q)+' items total';};const updateTile=()=>{const x=Math.min(8,Math.max(0,Math.floor(Number($('#tileX').value)||0))),z=Math.min(8,Math.max(0,Math.floor(Number($('#tileZ').value)||0))),hq=x===4&&z===4,xx=x*96+(hq?21:22),zz=z*96+(hq?21:22);$('#tileOutput').textContent=`Tile X${x*96}..${x*96+95}, Z${z*96}..${z*96+95}\nNorth road Z${z*96}..${z*96+11}\nWest road X${x*96}..${x*96+11}\n${hq?'HQ':'Hall'} X${xx}..${x*96+85}, Z${zz}..${z*96+85}`;};const updateCoord=()=>{const d=designMap.get($('#coordPlot').value),x=Math.trunc(Number($('#coordX').value)||0),z=Math.trunc(Number($('#coordZ').value)||0),b=d.site_bounds;$('#coordOutput').textContent=`City X${b[0]+x}, Z${b[1]+z}\n${x<0||z<0||x>d.dimensions_x_y_z[0]-1||z>d.dimensions_x_y_z[2]-1?'Outside this model footprint.':'Inside the reserved model footprint.'}\nWorld anchor / surface S / rotation unassigned`;};['stackItems','stackSize'].forEach(id=>$('#'+id).oninput=updateStacks);['tileX','tileZ'].forEach(id=>$('#'+id).oninput=updateTile);['coordPlot','coordX','coordZ'].forEach(id=>{$('#'+id).oninput=updateCoord;});updateStacks();updateTile();updateCoord();}
function renderAbout(){headingCrumb('Sources & design status');content.innerHTML=title('WHAT THIS ATLAS CONTAINS','Design data you can trace.','The atlas packages the current Valier project for viewing and planning. Its models, inventories and coordinate conventions remain the source of every measured drawing.')+`<div class="tool-grid"><section class="panel tool-card"><h2>Fixed city baseline</h2><p>The core is 864 × 864 blocks. External east/south closing roads make the civil envelope 876 × 876. All 81 purposes remain assigned. HQ uses X/Z405..469, a 65-square reservation.</p><p>Local northwest origin. +X east; +Z south. Civil Y0 is future walkable surface S. The intended PDIM is not created, so its world origin, dimension, rotation and measured S remain unassigned.</p></section><section class="panel tool-card"><h2>Models and material evidence</h2><p>96 coordinate studies supply 2,899 model layers and 1,057 disjoint assembly stages. Steam Works v2 remains unchanged. Other exterior studies do not establish functional factories or accessible interiors.</p><p>Registry names and metadata use installed-file evidence. Dirt/oak and dry-glass role bindings are proposed construction choices. Recipes, progression, live-game collision, lighting and import remain open.</p></section><section class="panel tool-card"><h2>Images are labeled by source</h2><p>Design cards, plans, facades, progress drawings and layers are coordinate-derived. Palette swatches use installed base textures, with explicitly illustrative cyan/leaf tint.</p><p>The three AI atmosphere boards are separate visual concepts. They do not define dimensions, exact blocks, bridges, flowers or sign text.</p></section><section class="panel tool-card"><h2>Viewing and downloads</h2><p>The site includes published copies of selected design assets, palettes, coordinate packs and authored guides. Original archives, source chat, raw game evidence and local world files are not part of this atlas.</p><p>No control on this site places structures, edits a save or marks actual construction complete.</p></section></div>`;}

async function route(){if(!atlas)return;const routeEpoch=++epoch;const hash=location.hash.slice(1)||'city',[path,query='']=hash.split('?'),[name,id]=path.split('/'),params=new URLSearchParams(query);currentRoute=name;mainViewer?.destroy();mainViewer=null;activeViewer=null;layerContext=null;$('#sidebar').classList.remove('open');$$('.nav-link').forEach(a=>a.classList.toggle('active',a.dataset.route===(name==='design'?'designs':name)));window.scrollTo({top:0,behavior:'instant'});if(name==='city')renderCity();else if(name==='designs')renderLibrary(false);else if(name==='guides')renderLibrary(true);else if(name==='design')await renderDesign(id,params);else if(name==='blocks')renderBlocks();else if(name==='installed')await renderInstalledLibrary({content,title,headingCrumb,viewerShell,showImage,downloadLinks,number,isCurrent:()=>epoch===routeEpoch});else if(name==='infrastructure')renderInfrastructure(params);else if(name==='references')renderReferences();else if(name==='shapes')await renderShapes({content,title,headingCrumb,viewerShell,showImage,downloadLinks,table,number,mountViewer,isCurrent:()=>epoch===routeEpoch},id,params);else if(name==='style')await renderConceptMatch({content,title,headingCrumb,viewerShell,showImage,downloadLinks,table,number,bindImages,mountViewer,isCurrent:()=>epoch===routeEpoch},id,params);else if(name==='tools')renderTools();else if(name==='operations')await renderOperations({content,title,headingCrumb,viewerShell,mountViewer,table,downloadLinks,number,isCurrent:()=>epoch===routeEpoch},id,params);else if(name==='about')renderAbout();else go('city');}
$('#globalSearch').addEventListener('input',e=>{search=e.target.value.trim();clearTimeout(route.searchTimer);route.searchTimer=setTimeout(()=>{if(['designs','guides'].includes(currentRoute))renderCards(currentRoute==='guides');else if(currentRoute==='blocks')renderBlockCards();else if(currentRoute==='city')mainViewer?.draw();else go('designs');},130);});$('#globalSearch').addEventListener('keydown',e=>{if(e.key==='Enter'&&search&&!['designs','guides','blocks'].includes(currentRoute))go('designs');});document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();$('#globalSearch').focus();$('#globalSearch').select();}});window.addEventListener('hashchange',route);
try{const response=await fetch('data/atlas.json?v=32c6535889d67e82');if(!response.ok)throw Error('Atlas data is unavailable');atlas=await response.json();designMap=new Map(atlas.designs.map(d=>[d.id,d]));paletteMap=new Map(atlas.palette.map(p=>[p.role,p]));await route();}catch(e){content.innerHTML=`<div class="empty-state"><h1>The atlas could not open</h1><p>${esc(e.message)}</p><button class="button" id="retryLoad">Try again</button></div>`;$('#retryLoad').onclick=()=>location.reload();}
